/**
 * PMT 赛况页的「本页目录」数据（Layout 左侧目录浮窗的 entries）。
 *
 * 目录条目要能滚动跳转，靠的是 id 与 DOM 上的 id 完全一致，所以 id 的拼法只在这里写一次，
 * 页面（pmtPlayer.vue）登记目录、卡片（pmtSCard.vue）渲染锚点都调这里的函数：
 *   - 赛况：每个赛段是一级分组（id = pmt-stage-<赛段序号>），
 *           组内每张分组卡是二级条目（id = pmt-group-<赛段序号>-<分组序号>）——
 *           分组名在不同赛段里会重名（都有「常规组A」），所以 id 必须带赛段序号
 *   - 排名：3强 / 8强 / 16强… 各一节（id = pmt-rank-<序号>），前三名在页面上已合并成「3强」
 *   - 预选：选手卡是一张张平铺的，没有可跳的分区，返回空数组让目录不显示
 */

export const stageAnchorId = (stageIndex) => `pmt-stage-${stageIndex}`

export const groupAnchorId = (stageIndex, groupIndex) => `pmt-group-${stageIndex}-${groupIndex}`

export const rankAnchorId = (rankIndex) => `pmt-rank-${rankIndex}`

/** 赛况：赛段（一级，可折叠）→ 分组（二级条目） */
export function buildMatchSections(matchList) {
  if (!matchList || typeof matchList !== 'object') return []
  return Object.keys(matchList).map((stageName, stageIndex) => {
    const stage = matchList[stageName]
    const groupNames = stage && typeof stage === 'object' ? Object.keys(stage) : []
    return {
      id: stageAnchorId(stageIndex),
      label: stageName,
      icon: 'flag-outline',
      children: groupNames.map((groupName, groupIndex) => ({
        id: groupAnchorId(stageIndex, groupIndex),
        label: groupName,
        icon: 'view-grid-outline'
      }))
    }
  })
}

/** 排名：一页一节（3强 / 8强 / 16强…），次序与页面渲染的分节一致 */
export function buildRankSections(sections) {
  if (!Array.isArray(sections)) return []
  return sections.map((section, index) => ({
    id: rankAnchorId(index),
    label: section.key,
    icon: section.top3 ? 'star-outline' : 'table-large'
  }))
}
